import sys

def solve():
    try:
        input_data = sys.stdin.read().split()
        if not input_data:
            return
        X = int(input_data[0])
    except ValueError:
        return

    n = 1
    fact = 1

    # Since X >= 2, N will be at least 2.
    # We can start checking from n=2.

    while fact < X:
        n += 1
        fact *= n

    if fact == X:
        print(n)
    else:
        # This part should theoretically not be reached given the problem statement
        # "There is exactly one positive integer N such that N!=X"
        pass

if __name__ == '__main__':
    solve()

